import { delegateActions } from 'kerfjs/actions';
import { SegmentedControl } from '@kerfjs/ui/segmented-control';

export function mountChoice(root: HTMLElement, value: string) {
  const off = delegateActions(root, 'click', { 'set-view': (_event, target) => console.log(target.dataset.segmentValue) });
  const view = <SegmentedControl ariaLabel="Workspace view" action="set-view" value={value} choices={[{ value: 'board', label: 'Board' }, { value: 'list', label: 'List' }, { value: 'timeline', label: 'Timeline' }]} appearance="toolbar" />;
  return { view, dispose: off };
}
